mapper.select:
SELECT a.factory_id 'factory.id', a.id 'production_line.id', a.workshop_id 'workshop.id', mbf.`name` 'factory.name', mbw.`name` 'workshop.name', a.`name` 'production_line.name' FROM mes_enclosure_production_line a LEFT JOIN mes_enclosure_factory mbf ON mbf.id=a.factory_id LEFT JOIN mes_enclosure_workshop mbw ON mbw.id=a.workshop_id
a.factory_id=#{factory}
a.workshop_id=#{workshopId}

SELECT mbpl.id 'productionLine.id', mbpl.`name` 'productionLine.name', mbw.id 'workshop.id', mbw.`name` 'workshop.name', mbf.id 'factory.id', mbf.`name` 'factory.name' FROM ( SELECT DISTINCT production_line_id id FROM mes_enclosure_team team LEFT JOIN mes_enclosure_process process ON team.process_id = process.id
team.bool_delete_enum = FALSE
AND team.factory_id=#{factoryId}
AND team.workshop_id=#{factoryId}
AND process.product_type=#{productType}
AND team.id=#{productionLineId}
) a LEFT JOIN mes_enclosure_production_line mbpl ON mbpl.id =a.id LEFT JOIN mes_enclosure_workshop mbw ON mbpl.workshop_id = mbw.id LEFT JOIN mes_enclosure_factory mbf ON mbpl.factory_id = mbf.id WHERE mbpl.bool_delete_enum=FALSE ORDER BY mbpl.factory_id

SELECT line.*, factory.name factoryName, workshop.name workshopName FROM mes_enclosure_production_line line LEFT JOIN mes_enclosure_factory factory ON line.factory_id = factory.id AND factory.bool_delete_enum = 0 AND factory.bool_enabled_enum=1 LEFT JOIN mes_enclosure_workshop workshop ON line.workshop_id = workshop.id AND workshop.bool_delete_enum = 0 AND workshop.bool_enabled_enum=1 WHERE line.bool_delete_enum = 0 AND line.bool_enabled_enum=1
AND line.factory_id = #{factoryId}
AND line.workshop_id = #{workshopId}
AND line.id = #{productionLineId}
AND line.product_type= #{productType}
ORDER BY workshop.`id` ASC ,line.`id` ASC

SELECT line.*, factory.name factoryName, workshop.name workshopName FROM mes_enclosure_production_line line LEFT JOIN mes_enclosure_factory factory ON line.factory_id = factory.id AND factory.bool_delete_enum = 0 AND factory.bool_enabled_enum=1 LEFT JOIN mes_enclosure_workshop workshop ON line.workshop_id = workshop.id AND workshop.bool_delete_enum = 0 AND workshop.bool_enabled_enum=1 WHERE line.bool_delete_enum = 0 AND line.bool_enabled_enum=1
and line.id in
#{item}
